import{_ as a,o as d,c as e,a2 as r}from"./chunks/framework.CqpfiAoK.js";const c=JSON.parse('{"title":"Межплоскостные Этические Нормы","description":"","frontmatter":{},"headers":[],"relativePath":"ru/88-跨位面伦理准则.md","filePath":"ru/88-跨位面伦理准则.md","lastUpdated":null}'),i={name:"ru/88-跨位面伦理准则.md"};function l(h,t,o,n,p,s){return d(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="межплоскостные-этические-нормы" tabindex="-1">Межплоскостные Этические Нормы <a class="header-anchor" href="#межплоскостные-этические-нормы" aria-label="Permalink to &quot;Межплоскостные Этические Нормы&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Позиция</th><th>Содержание</th></tr></thead><tbody><tr><td>Номер документа</td><td>88</td></tr><tr><td>Модуль</td><td>Межплоскостное взаимодействие и правила времени</td></tr><tr><td>Ключевые слова</td><td>межплоскостная этика, субъектность цивилизации, невмешательство, уважение культуры, симбиотическая дипломатия</td></tr></tbody></table><h2 id="i-философское-основание-этических-норм" tabindex="-1">I. Философское Основание Этических Норм <a class="header-anchor" href="#i-философское-основание-этических-норм" aria-label="Permalink to &quot;I. Философское Основание Этических Норм&quot;">​</a></h2><p>Межплоскостные этические нормы — это моральные нормы и кодексы поведения, которым Симбиотическая Цивилизация Якоря должна следовать при взаимодействии с цивилизациями других плоскостей. Их философское основание — принцип «субъектности цивилизации» — каждая цивилизация каждой плоскости, независимо от уровня её развития, расовой формы и социального строя, обладает неотъемлемой субъектностью и правом на самостоятельное развитие. Ни одна чужая цивилизация не может лишить этой субъектности по какой-либо причине или навязывать свою волю другим цивилизациям.</p><p>Установление этого философского основания идёт в одном русле с центральной концепцией «анти-хищничества» Симбиотической Цивилизации Якоря. Сущностная черта хищнической цивилизации — непризнание субъектности других цивилизаций, отношение к другим цивилизациям как к ресурсам, которые можно использовать, или объектам, которые можно покорить. Чтобы по-настоящему превзойти хищнические цивилизации, Симбиотическая Цивилизация Якоря должна полностью отказаться от такого умонастроения в межплоскостном взаимодействии, относясь к каждой встреченной цивилизации с равенством, уважением и симбиозом.</p><p>Сфера действия межплоскостных этических норм охватывает все виды межплоскостного взаимодействия, включая, но не ограничиваясь: межплоскостную навигацию, межплоскостную связь, археологическую деятельность, торговые обмены, культурные обмены, техническое сотрудничество, а также гуманитарное вмешательство в чрезвычайных ситуациях. Любая организация и любое лицо, осуществляющие межплоскостное взаимодействие, обязаны соблюдать все положения настоящих норм.</p><h2 id="ii-шесть-этических-принципов" tabindex="-1">II. Шесть Этических Принципов <a class="header-anchor" href="#ii-шесть-этических-принципов" aria-label="Permalink to &quot;II. Шесть Этических Принципов&quot;">​</a></h2><p>Межплоскостные этические нормы состоят из шести основных принципов, образующих целостную систему этических ценностей:</p><table tabindex="0"><thead><tr><th>Принцип</th><th>Центральное содержание</th><th>Конкретные требования</th></tr></thead><tbody><tr><td>Принцип Самостоятельности Цивилизации</td><td>Уважать право на самостоятельное развитие цивилизации целевой плоскости, не вмешиваться насильно в её внутренние дела</td><td>Не изменять насильно общественный строй, идеологию и путь развития целевой цивилизации; не взращивать в целевой цивилизации агентов или марионеточные режимы</td></tr><tr><td>Принцип Невмешательства</td><td>За исключением случая, когда целевая цивилизация сталкивается с кризисом уровня вымирания и активно просит помощи, никакого существенного вмешательства не проводится</td><td>Не вмешиваться во внутренние конфликты целевой цивилизации; не предоставлять оружие или военную помощь какой-либо стороне целевой цивилизации; не манипулировать общественным мнением и политическими процессами целевой цивилизации</td></tr><tr><td>Принцип Уважения Культуры</td><td>Уважать культурные традиции, религиозные верования и обычаи целевой цивилизации</td><td>Не давать дискриминационных оценок и злонамеренных насмешек над культурой целевой цивилизации; не навязывать насильно культурные продукты и ценности собственной плоскости; не проводить культурную ассимиляцию под предлогом «цивилизации»</td></tr><tr><td>Принцип Равенства и Взаимной Выгоды</td><td>Межплоскостные отношения должны строиться на равенстве, обеспечивая выгоду обеих сторон от взаимодействия</td><td>Не использовать технологические преимущества для неравноправной торговли; не грабить ресурсы целевой цивилизации; при экспорте технологий учитывать способность целевой цивилизации к восприятию и социальные последствия</td></tr><tr><td>Принцип Минимального Воздействия</td><td>Межплоскостное взаимодействие должно максимально сокращать внешнее воздействие на целевую цивилизацию</td><td>Предпочитать методы взаимодействия с низким контактом и низким вмешательством; сферу и интенсивность взаимодействия строго ограничивать необходимыми пределами; после взаимодействия оценивать и устранять ненужные остаточные воздействия</td></tr><tr><td>Принцип Подотчётности</td><td>Все межплоскостные взаимодействия должны быть прослеживаемыми, контролируемыми и подотчётными</td><td>Создавать полные архивы и журналы взаимодействий; учреждать независимый орган этического надзора; расследовать и наказывать действия, нарушающие этические нормы</td></tr></tbody></table><p>Между шестью принципами существует внутренняя логическая связь: Принцип Самостоятельности Цивилизации — фундаментальная ценность, Принцип Невмешательства — центральное требование, Принцип Уважения Культуры — проявление на культурном уровне, Принцип Равенства и Взаимной Выгоды — гарантия на экономическом уровне, Принцип Минимального Воздействия — норма на операционном уровне, Принцип Подотчётности — ограничение на институциональном уровне. Шесть вместе образуют полный этический цикл «ценность — требование — проявление — гарантия — норма — ограничение».</p><h2 id="iii-этические-нормы-для-различных-сценариев-взаимодеиствия" tabindex="-1">III. Этические Нормы для Различных Сценариев Взаимодействия <a class="header-anchor" href="#iii-этические-нормы-для-различных-сценариев-взаимодеиствия" aria-label="Permalink to &quot;III. Этические Нормы для Различных Сценариев Взаимодействия&quot;">​</a></h2><h3 id="_3-1-этические-нормы-для-археологических-сценариев" tabindex="-1">3.1 Этические Нормы для Археологических Сценариев <a class="header-anchor" href="#_3-1-этические-нормы-для-археологических-сценариев" aria-label="Permalink to &quot;3.1 Этические Нормы для Археологических Сценариев&quot;">​</a></h3><p>Межплоскостная археология — один из самых распространённых сценариев взаимодействия, и ядро её этических норм — «не вмешиваться». Археологическая команда должна строго следовать стандартной схеме Зеркало Репликации + Изолированное Пространство + Передача Только Знаний, обеспечивая, чтобы археологический процесс не был замечен целевой цивилизацией. Для плоскостей, где ещё существует живая цивилизация, сфера археологии должна быть строго ограничена заброшенными зонами руин; никакие формы сканирования или репликации зон проживания живой цивилизации не допускаются.</p><p>Когда знания, обнаруженные археологией, передаются и публикуются, необходимо уважать культурную чувствительность целевой цивилизации. Если археологические находки касаются религиозных святынь, останков предков или культурных табу целевой цивилизации, соответствующая информация перед публикацией должна пройти проверку культурной чувствительности Межплоскостным Этическим Комитетом, а чувствительные детали при необходимости должны быть размыты.</p><h3 id="_3-2-этические-нормы-для-коммуникационных-сценариев" tabindex="-1">3.2 Этические Нормы для Коммуникационных Сценариев <a class="header-anchor" href="#_3-2-этические-нормы-для-коммуникационных-сценариев" aria-label="Permalink to &quot;3.2 Этические Нормы для Коммуникационных Сценариев&quot;">​</a></h3><p>Межплоскостная связь — способ прямого общения с целевой цивилизацией, и ядро её этических норм — «искренность и уважение». Содержание общения должно быть правдивым, без намеренного предоставления ложной информации или обманной пропаганды; тон общения должен быть равным, без снисходительного отношения к цивилизациям с более низким уровнем развития; темы общения должны быть одобрены целевой цивилизацией, без насильственного навязывания идеологии или религиозных верований собственной плоскости.</p><p>При установлении связи с неизвестной цивилизацией впервые необходимо следовать норме «постепенного контакта»: сначала отправить нейтральные математические и физические сигналы для подтверждения уровня интеллекта и способности к общению другой стороны, затем на основе ответа другой стороны постепенно расширять сферу обмена; при первом контакте нельзя отправлять сложную культурную или техническую информацию.</p><h3 id="_3-3-этические-нормы-для-торговых-сценариев" tabindex="-1">3.3 Этические Нормы для Торговых Сценариев <a class="header-anchor" href="#_3-3-этические-нормы-для-торговых-сценариев" aria-label="Permalink to &quot;3.3 Этические Нормы для Торговых Сценариев&quot;">​</a></h3><p>Ядро этических норм межплоскостной торговли — «справедливость и устойчивость». Торговля должна основываться на добровольном согласии обеих сторон, без использования информационной асимметрии или технологических преимуществ для принудительных сделок; торговые цены должны быть справедливыми, без хищнического ценообразования; торговые товары не должны включать содержимое, способное вызвать социальный шок или экологический ущерб у целевой цивилизации.</p><p>Особое внимание следует уделить тому, что межплоскостная торговля культивационными технологиями и высокоэнергетическим оружием подлежит самым строгим этическим ограничениям. Экспорт культивационных технологий высокого уровня цивилизациям с более низким уровнем развития может привести к дисбалансу их социальных структур и обострению внутренних конфликтов; экспорт оружия может напрямую спровоцировать войны. Поэтому эти два вида торговли в принципе запрещены и могут осуществляться только в исключительно особых обстоятельствах после одобрения пленарным заседанием Собрания Якоря.</p><h3 id="_3-4-этические-нормы-для-сценариев-экстренного-вмешательства" tabindex="-1">3.4 Этические Нормы для Сценариев Экстренного Вмешательства <a class="header-anchor" href="#_3-4-этические-нормы-для-сценариев-экстренного-вмешательства" aria-label="Permalink to &quot;3.4 Этические Нормы для Сценариев Экстренного Вмешательства&quot;">​</a></h3><p>Когда цивилизация целевой плоскости сталкивается с кризисом уровня вымирания (таким как удар астероида, суперэпидемия, крах законов), Симбиотическая Цивилизация Якоря может провести гуманитарное вмешательство. Но даже в таких чрезвычайных ситуациях необходимо соблюдать следующие этические нормы:</p><ul><li>Перед вмешательством следует как можно больше получить информированное согласие целевой цивилизации; если целевая цивилизация не может эффективно ответить из-за кризиса, Межплоскостной Этический Комитет выносит от её имени суждение «предполагаемого согласия»</li><li>Средства вмешательства должны выбирать схему с наименьшим воздействием на целевую цивилизацию, предпочитая косвенное вмешательство (например, изменение орбиты астероида) прямому вмешательству (например, прямое прибытие для спасения)</li><li>Во время вмешательства нельзя пользоваться случаем для получения ресурсов или технологий целевой цивилизации</li><li>После окончания вмешательства требуется немедленный вывод, без оставления постоянного присутствия на целевой плоскости</li><li>Впоследствии необходимо представить полный отчёт о вмешательстве в Межплоскостной Этический Комитет для этической проверки</li></ul><h2 id="iv-этическии-надзор-и-рассмотрение-нарушении" tabindex="-1">IV. Этический Надзор и Рассмотрение Нарушений <a class="header-anchor" href="#iv-этическии-надзор-и-рассмотрение-нарушении" aria-label="Permalink to &quot;IV. Этический Надзор и Рассмотрение Нарушений&quot;">​</a></h2><p>Вселенная Хэнъюань учредила «Межплоскостной Этический Комитет» как независимый орган этического надзора, ответственный за разработку и толкование межплоскостных этических норм, одобрение высокорисковых проектов межплоскостного взаимодействия, приём жалоб на этические нарушения, а также расследование и вынесение решений по нарушениям. Комитет состоит из этиков, юристов, учёных и представителей цивилизаций из разных рас и разных профессиональных сфер, что обеспечивает многообразие и беспристрастность решений.</p><p>За действия, нарушающие межплоскостные этические нормы, в зависимости от тяжести обстоятельств меры включают: устное предупреждение, письменное порицание, приостановление квалификации межплоскостного взаимодействия, лишение навигационного разрешения, штрафы, лишение свободы и в крайних случаях «плоскостное изгнание» (лишение права проживания в основных плоскостях Вселенной Хэнъюань). Все результаты рассмотрения этических нарушений заносятся в этические досье лица или организации и хранятся постоянно.</p><h2 id="заключение" tabindex="-1">Заключение <a class="header-anchor" href="#заключение" aria-label="Permalink to &quot;Заключение&quot;">​</a></h2><p>Межплоскостные этические нормы — концентрированное проявление нравственной высоты Симбиотической Цивилизации Якоря. Они не только предписывают «что нельзя делать», но и провозглашают «чем следует стать» — по-настоящему великая цивилизация — это не та, которая покорила много других цивилизаций, а та, которая уважала субъектность многих других цивилизаций. На пути Вселенной Хэнъюань к межзвёздному симбиозу межплоскостные этические нормы всегда будут нравственным маяком, указывающим направление.</p><h2 id="связанные-документы" tabindex="-1">Связанные Документы <a class="header-anchor" href="#связанные-документы" aria-label="Permalink to &quot;Связанные Документы&quot;">​</a></h2><ul><li>81-位面穿梭规则 (Правила Межплоскостной Навигации)</li><li>87-仅回传知识原则 (Принцип Передачи Только Знаний)</li><li>04-反掠夺主义核心论纲 (Центральная теория анти-хищничества)</li></ul>',30)])])}const u=a(i,[["render",l]]);export{c as __pageData,u as default};
